class Solution
{
    int count = 0;
    bool dfs(TreeNode*node)
    {
        if (!node)
        {
            return true;
        }
        bool a = dfs(node->left), b = dfs(node->right);
        if (!a || !b)
        {
            return false;
        }
        if (node->left && node->left->val != node->val)
        {
            return false;
        }
        if (node->right && node->right->val != node->val)
        {
            return false;
        }
        ++count;
        return true;
    }
public:
    int countUnivalSubtrees(TreeNode*root)
    {
        dfs(root);
        return count;
    }
};
